(function(){'use strict';
const KEY='nawaf-hq-v5';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s,reason='v13'){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason}}));window.dispatchEvent(new CustomEvent('nawaf:activity-updated'))}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function uid(p){return p+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
const ACTIVE=new Set(['WORKING','RESEARCHING','REVIEWING']);
function taskMeta(s,t){const e=(s.employees||[]).find(x=>x.id===t.employeeId),p=(s.projects||[]).find(x=>x.id===t.projectId);return {employee:e?.name||'موظف AI',project:p?.name||'عام'}}
function ensureCenter(){let p=$('.v13-center');if(p)return p;p=document.createElement('aside');p.className='v13-center';p.innerHTML='<div class="v13-head"><div><small>CEO CONTROL</small><h2>مركز قرارات نواف</h2></div><button type="button" data-v13-close aria-label="إغلاق">×</button></div><div class="v13-body"></div>';document.body.appendChild(p);p.querySelector('[data-v13-close]').onclick=()=>p.classList.remove('show');return p}
function logDecision(s,t,decision,note=''){s.decisions=Array.isArray(s.decisions)?s.decisions:[];const m=taskMeta(s,t);s.decisions.unshift({id:uid('d'),taskId:t.id,title:t.title,decision,note,employee:m.employee,project:m.project,at:new Date().toISOString()});s.decisions=s.decisions.slice(0,120);s.activity=Array.isArray(s.activity)?s.activity:[];s.activity.unshift({id:uid('a'),text:`قرار نواف: ${decision==='APPROVED'?'موافقة':'رفض'} — ${t.title}`,type:'DECISION',at:new Date().toISOString()})}
function approve(id){const s=read(),t=(s.tasks||[]).find(x=>x.id===id);if(!t)return;t.status='READY';t.progress=Math.max(0,Number(t.progress)||0);t.approvedAt=new Date().toISOString();t.approvedBy='NAWAF';delete t.blockedReason;delete t.executionStartedAt;const e=(s.employees||[]).find(x=>x.id===t.employeeId);if(e){e.status='READY';e.task=t.title}logDecision(s,t,'APPROVED');write(s,'ceo-approved');renderCenter();setTimeout(()=>{if(window.NawafProjectExecutor?.runTask&&['mueen','qaddha'].includes(t.projectId))window.NawafProjectExecutor.runTask(t.id).catch(()=>{});else window.NawafAgents?.runTask?.(t.id)?.catch?.(()=>{})},160)}
function reject(id){const s=read(),t=(s.tasks||[]).find(x=>x.id===id);if(!t)return;const note=prompt('سبب الرفض أو ملاحظة (اختياري):','')||'';t.status='PAUSED';t.rejectedAt=new Date().toISOString();t.rejectedBy='NAWAF';t.blockedReason=note||'أوقفها نواف';const e=(s.employees||[]).find(x=>x.id===t.employeeId);if(e){e.status='READY';e.task=''}logDecision(s,t,'REJECTED',note);write(s,'ceo-rejected');renderCenter()}
function reopen(id){const s=read(),t=(s.tasks||[]).find(x=>x.id===id);if(!t)return;t.status='READY';t.progress=0;delete t.rejectedAt;delete t.rejectedBy;delete t.blockedReason;write(s,'ceo-reopened');renderCenter()}
function renderCenter(){const p=ensureCenter(),s=read(),waiting=(s.tasks||[]).filter(t=>t.status==='WAITING_FOR_NAWAF'),paused=(s.tasks||[]).filter(t=>t.status==='PAUSED').slice(0,8),decisions=(s.decisions||[]).slice(0,12);p.querySelector('.v13-body').innerHTML=`<section class="v13-section"><div class="v13-section-title"><h3>تحتاج قرارك</h3><span>${waiting.length}</span></div>${waiting.length?waiting.map(t=>{const m=taskMeta(s,t);return `<article class="v13-decision"><div><b>${esc(t.title)}</b><small>${esc(m.employee)} • ${esc(m.project)}</small><p>${esc(t.blockedReason||t.aiResult?.summary||'المهمة متوقفة وتحتاج قرارك.')}</p></div><div class="v13-actions"><button type="button" class="approve" data-v13-approve="${esc(t.id)}">موافقة وإكمال</button><button type="button" data-v13-reject="${esc(t.id)}">رفض وإغلاق</button></div></article>`}).join(''):'<div class="v13-empty">ما فيه شيء يحتاج قرارك الآن.</div>'}</section><section class="v13-section"><div class="v13-section-title"><h3>الموقوفة</h3><span>${paused.length}</span></div>${paused.length?paused.map(t=>`<article class="v13-mini"><div><b>${esc(t.title)}</b><small>${esc(t.blockedReason||'متوقفة')}</small></div><button type="button" data-v13-reopen="${esc(t.id)}">إعادة فتح</button></article>`).join(''):'<div class="v13-empty">لا توجد مهام موقوفة.</div>'}</section><section class="v13-section"><div class="v13-section-title"><h3>آخر قراراتك</h3><span>${decisions.length}</span></div>${decisions.length?decisions.map(d=>`<article class="v13-history"><span class="${d.decision==='APPROVED'?'ok':'no'}">${d.decision==='APPROVED'?'موافقة':'رفض'}</span><div><b>${esc(d.title)}</b><small>${esc(d.employee)} • ${esc(d.project)} • ${new Date(d.at).toLocaleString('ar-SA')}</small>${d.note?`<p>${esc(d.note)}</p>`:''}</div></article>`).join(''):'<div class="v13-empty">قراراتك القادمة بتنحفظ هنا.</div>'}</section>`;p.querySelectorAll('[data-v13-approve]').forEach(b=>b.onclick=()=>approve(b.dataset.v13Approve));p.querySelectorAll('[data-v13-reject]').forEach(b=>b.onclick=()=>reject(b.dataset.v13Reject));p.querySelectorAll('[data-v13-reopen]').forEach(b=>b.onclick=()=>reopen(b.dataset.v13Reopen))}
function openCenter(){renderCenter();ensureCenter().classList.add('show')}
function injectCeoStrip(){const host=$('.v9-control-strip');if(!host)return;let box=$('.v13-ceo');const s=read(),tasks=s.tasks||[],active=tasks.filter(t=>ACTIVE.has(t.status)).length,waiting=tasks.filter(t=>t.status==='WAITING_FOR_NAWAF').length,done=tasks.filter(t=>t.status==='COMPLETED').length,failed=tasks.filter(t=>t.status==='READY'&&t.blockedReason).length;if(!box){box=document.createElement('button');box.type='button';box.className='v13-ceo';box.dataset.v13Center='1';host.appendChild(box);box.onclick=openCenter}box.innerHTML=`<span class="v13-ceo-mark">CEO</span><span><b>ملخصك التنفيذي</b><small>${active} يعمل • ${waiting} يحتاج قرار • ${done} مكتمل${failed?` • ${failed} متعثر`:''}</small></span><i>${waiting||''}</i>`}
function injectDeliverableBadges(){const s=read(),map=new Map((s.tasks||[]).map(t=>[t.id,t]));$$('.v8-row[data-task]').forEach(r=>{const t=map.get(r.dataset.task);if(!t||r.querySelector('.v13-task-chip'))return;let label='';if(t.status==='WAITING_FOR_NAWAF')label='قرارك';else if(t.status==='COMPLETED'&&t.aiResult?.deliverable)label='تسليم';else if(t.evidence?.length)label='أدلة';if(!label)return;const chip=document.createElement('span');chip.className='v13-task-chip '+(t.status==='WAITING_FOR_NAWAF'?'warn':'');chip.textContent=label;r.appendChild(chip)})}
function ceoBrief(){const s=read(),tasks=s.tasks||[],emps=s.employees||[],active=tasks.filter(t=>ACTIVE.has(t.status)),waiting=tasks.filter(t=>t.status==='WAITING_FOR_NAWAF'),done24=tasks.filter(t=>t.status==='COMPLETED'&&Date.now()-Date.parse(t.lastRunAt||t.createdAt||0)<86400000),busy=emps.filter(e=>ACTIVE.has(e.status));return {active:active.length,waiting:waiting.length,done24:done24.length,busy:busy.map(x=>x.name),topWaiting:waiting.slice(0,3).map(x=>x.title)}}
function enhance(){injectCeoStrip();injectDeliverableBadges()}
let timer;const obs=new MutationObserver(()=>{clearTimeout(timer);timer=setTimeout(enhance,90)});function boot(){enhance();obs.observe(document.body,{childList:true,subtree:true});window.addEventListener('nawaf:state-updated',()=>setTimeout(()=>{injectCeoStrip();renderCenter();injectDeliverableBadges()},100))}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();window.NawafHQV13={openCenter,approve,reject,reopen,brief:ceoBrief};
})();